/*
================================================================================
SCRIPT DEMO: sql/17_demo_simulate_incremental_1000_rows.sql
MỤC ĐÍCH: Giả lập 1.000 giao dịch mới phát sinh (Đơn hàng & Chuyến xe) trên CSDL OLTP
          để phục vụ KỊCH BẢN DEMO NẠP TĂNG TRƯỞNG (Incremental Load & CDC) trước Hội đồng.
NGUỒN DỮ LIỆU: Trích xuất chính xác 1.000 bản ghi lịch sử tiếp theo (07/2023)
               - loads: LOAD00042706 -> LOAD00043705
               - trips: TRIP00042706 -> TRIP00043705
CÁCH DÙNG KHI DEMO:
  1. Chạy BƯỚC 1 để xem số dòng hiện tại ở OLTP và DWH.
  2. Chạy BƯỚC 2 để INSERT 1.000 dòng mới vào Logistics_OLTP.
  3. Kích hoạt Job SQL Server Agent hoặc chạy Master_Orchestrator.dtsx.
  4. Chạy BƯỚC 3 để chứng minh DWH đã tự động tăng thêm 1.000 dòng mà không cần nạp lại từ đầu!
  5. (Tùy chọn) Chạy BƯỚC 4 để dọn dẹp trả lại trạng thái ban đầu nếu cần diễn tập lại.
================================================================================
*/

USE [Logistics_OLTP];
GO

PRINT '======================================================================';
PRINT 'BƯỚC 1: KIỂM TRA SỐ DÒNG HIỆN TẠI TRƯỚC KHI GIẢ LẬP PHÁT SINH MỚI';
PRINT '======================================================================';

SELECT 'OLTP.dbo.loads' AS TableName, COUNT(*) AS CurrentRowCount, MAX(load_date) AS MaxDate FROM Logistics_OLTP.dbo.loads
UNION ALL
SELECT 'OLTP.dbo.trips' AS TableName, COUNT(*) AS CurrentRowCount, MAX(dispatch_date) AS MaxDate FROM Logistics_OLTP.dbo.trips
UNION ALL
SELECT 'DWH.dbo.Fact_Load' AS TableName, COUNT(*) AS CurrentRowCount, NULL FROM Logistics_DW.dbo.Fact_Load
UNION ALL
SELECT 'DWH.dbo.Fact_Trip' AS TableName, COUNT(*) AS CurrentRowCount, NULL FROM Logistics_DW.dbo.Fact_Trip;
GO

PRINT '======================================================================';
PRINT 'BƯỚC 2: TIẾN HÀNH GIẢ LẬP INSERT 1.000 ĐƠN HÀNG VÀ CHUYẾN XE MỚI VÀO OLTP';
PRINT '======================================================================';

IF EXISTS (SELECT 1 FROM dbo.loads WHERE load_id = 'LOAD00042706')
BEGIN
    PRINT '-> CẢNH BÁO: Dữ liệu 1.000 dòng demo này đã được nạp trước đó!';
    PRINT '-> Nếu muốn nạp lại từ đầu, vui lòng chạy BƯỚC 4 ở cuối file để Reset.';
END
ELSE
BEGIN
    BEGIN TRANSACTION;

    PRINT '-> Đang nạp 1.000 đơn hàng mới vào Logistics_OLTP.dbo.loads...';

    PRINT '-> Đang nạp 1.000 chuyến xe mới vào Logistics_OLTP.dbo.trips...';

    COMMIT TRANSACTION;
    PRINT '-> [THÀNH CÔNG] Đã phát sinh 1.000 giao dịch mới trong CSDL OLTP!';
    PRINT '-> Bộ cảm biến CDC của SQL Server đã ghi nhận các thay đổi này.';
    PRINT '-> BÂY GIỜ BẠN CÓ THỂ KÍCH HOẠT JOB SQL AGENT ĐỂ THẤY PIPELINE TỰ ĐỘNG NẠP TĂNG CƯỜNG VÀO DWH.';
END
GO

PRINT '======================================================================';
PRINT 'BƯỚC 3: CÂU LỆNH KIỂM TRA ĐỐI SOÁT SAU KHI CHẠY PIPELINE ETL';
PRINT '======================================================================';
/*
-- HƯỚNG DẪN: Sau khi bạn chạy Job SQL Server Agent hoặc SSIS, mở tab này chạy câu dưới đây:
-- Kết quả Fact_Load và Fact_Trip trong DWH sẽ tự động TĂNG THÊM ĐÚNG 1.000 DÒNG!

SELECT 'DWH.dbo.Fact_Load' AS TableName, COUNT(*) AS RowCountAfterETL FROM Logistics_DW.dbo.Fact_Load
UNION ALL
SELECT 'DWH.dbo.Fact_Trip' AS TableName, COUNT(*) AS RowCountAfterETL FROM Logistics_DW.dbo.Fact_Trip
UNION ALL
SELECT 'Audit.Package_Log (Lần chạy mới nhất)', inserted_row_count FROM Logistics_Staging.audit.Package_Log 
WHERE package_name = 'Fact_Load.dtsx' AND package_log_id = (SELECT MAX(package_log_id) FROM Logistics_Staging.audit.Package_Log WHERE package_name = 'Fact_Load.dtsx');
*/
GO

PRINT '======================================================================';
PRINT 'BƯỚC 4: (TÙY CHỌN) LỆNH DỌN DẸP / RESET ĐỂ DIỄN TẬP DEMO NHIỀU LẦN';
PRINT '======================================================================';
/*
-- Nếu muốn quay lại trạng thái ban đầu để diễn tập lại:
BEGIN TRANSACTION;
DELETE FROM Logistics_OLTP.dbo.trips WHERE trip_id >= 'TRIP00042706' AND trip_id <= 'TRIP00043705';
DELETE FROM Logistics_OLTP.dbo.loads WHERE load_id >= 'LOAD00042706' AND load_id <= 'LOAD00043705';
DELETE FROM Logistics_DW.dbo.Fact_Trip WHERE trip_id >= 'TRIP00042706' AND trip_id <= 'TRIP00043705';
DELETE FROM Logistics_DW.dbo.Fact_Load WHERE load_id >= 'LOAD00042706' AND load_id <= 'LOAD00043705';
COMMIT TRANSACTION;
PRINT '-> Đã Reset sạch 1.000 dòng demo trên cả OLTP và DWH!';
*/
GO
